<?php require_once 'config.php';require_login();$page_title='Surat Pengantar';$page_desc='Pengajuan dan pengelolaan surat pengantar warga.';if($_SERVER['REQUEST_METHOD']==='POST'){$status=is_admin()?'Disetujui':'Menunggu';$s=$pdo->prepare('INSERT INTO surat(warga_id,tanggal,jenis,status) VALUES(?,?,?,?)');$s->execute([(int)$_POST['warga_id'],date('Y-m-d'),trim($_POST['jenis']),$status]);flash('success','Permohonan surat berhasil dibuat.');header('Location: surat.php');exit;}$warga=$pdo->query('SELECT id,nama FROM warga ORDER BY nama')->fetchAll();$rows=$pdo->query('SELECT s.*,w.nama FROM surat s JOIN warga w ON w.id=s.warga_id ORDER BY s.id DESC')->fetchAll();require 'partials/header.php';?><section class="panel form-panel"><div class="panel-head"><h3>Ajukan Surat Pengantar</h3></div><form method="post" class="form-grid"><div><label>Nama Pemohon</label><select name="warga_id"><?php foreach($warga as $w): ?><option value="<?=$w['id']?>"><?=e($w['nama'])?></option><?php endforeach;?></select></div><div><label>Jenis Surat</label><select name="jenis"><option>Surat Pengantar Domisili</option><option>Surat Pengantar SKCK</option><option>Surat Pengantar Keterangan Usaha</option><option>Surat Pengantar Lainnya</option></select></div><div><button class="btn primary">📄 Ajukan Surat</button></div></form></section><section class="panel"><div class="panel-head"><h3>Daftar Permohonan</h3></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Pemohon</th><th>Jenis Surat</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $s): ?><tr><td><?=date('d-m-Y',strtotime($s['tanggal']))?></td><td><?=e($s['nama'])?></td><td><?=e($s['jenis'])?></td><td><span class="badge <?=($s['status']==='Disetujui'?'success-badge':'')?>"><?=e($s['status'])?></span></td><td><button class="btn small" onclick="alert('Surat untuk <?=e($s['nama'])?> siap dicetak.')">Cetak / Download</button></td></tr><?php endforeach;?></tbody></table></div></section><?php require 'partials/footer.php';?>
